/**
 * How Millet circle (`awa-no-maru`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/awa-no-maru";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Curve long stems and leaves around an open circle. Place a nearly level seed head above the smaller upright head. Leave a clear space between the leaf tips on the right.","ja":"開いた円に沿って長い茎と葉を曲げます。小さく立った穂の上にほぼ水平の穂を置き、右側の葉先の間を白く残します。"};

export default construction;
export { construction, description };
